def rd(p):
    return io.open(p, encoding="utf-8").read()


def wr(p, s):
    io.open(p, "w", encoding="utf-8").write(s)


def sub(doc, old, new, tag):
    n = doc.count(old)
    assert n == 1, "[%s] 锚点命中 %d 次（需 1）" % (tag, n)
    return doc.replace(old, new, 1)


def subline(doc, prefix, new, tag):
    """把以 prefix 开头的那一行整行换成 new（new 可含 \n ⇒ 一行变多行）。"""
    lines = doc.split("\n")
    hit = [i for i, l in enumerate(lines) if l.startswith(prefix)]
    assert len(hit) == 1, "[%s] 行前缀命中 %d 行（需 1）：%s" % (tag, len(hit), prefix)
    lines[hit[0]] = new
    return "\n".join(lines)


